CORE_INFERENCE = "
def tiled(model,x,tile=384,overlap=64):
    if tile<=overlap or overlap<0: raise ValueError('Require 0 <= overlap < tile')
    h,w=x.shape[-2:]
    if h<=tile and w<=tile: return model(x).float()
    def starts(n):
        if n<=tile: return [0]
        return sorted(set(list(range(0,n-tile+1,tile-overlap))+[n-tile]))
    out=torch.zeros_like(x,dtype=torch.float32); weights=torch.zeros_like(x[:,:1],dtype=torch.float32)
    for top in starts(h):
        for left in starts(w):
            patch=x[...,top:top+tile,left:left+tile]; ph,pw=patch.shape[-2:]
            wy=torch.hann_window(ph,periodic=False,device=x.device).clamp_min(.05)
            wx=torch.hann_window(pw,periodic=False,device=x.device).clamp_min(.05)
            weight=(wy[:,None]*wx[None,:])[None,None]
            out[...,top:top+ph,left:left+pw]+=model(patch).float()*weight
            weights[...,top:top+ph,left:left+pw]+=weight
    return out/weights

def transform(x,k,flip):
    x=torch.rot90(x,k,(-2,-1))
    return x.flip(-1) if flip else x

def invert(x,k,flip):
    if flip: x=x.flip(-1)
    return torch.rot90(x,-k,(-2,-1))

@torch.inference_mode()
def predict(model,array,device,tile=384,overlap=64,tta=False):
    x=torch.from_numpy(np.ascontiguousarray(array.transpose(2,0,1))).float()[None].to(device)/255
    total=torch.zeros_like(x,dtype=torch.float32)
    variants=[(k,f) for k in range(4) for f in (False,True)] if tta else [(0,False)]
    model.eval()
    for k,f in variants:
        z=transform(x,k,f)
        out=tiled(model,z,tile,overlap)
        total+=invert(out,k,f)
    result=(total/len(variants)).clamp(0,1)[0].permute(1,2,0).cpu().numpy()
    if not np.isfinite(result).all(): raise FloatingPointError('Nonfinite prediction')
    return result

def wavelet_prediction(array):
    from skimage.restoration import denoise_wavelet
    x=array.astype(np.float32)/255
    if x.shape[-1]==1:
        out=denoise_wavelet(x[...,0],method='BayesShrink',mode='soft',rescale_sigma=True,channel_axis=None)[...,None]
    else:
        out=denoise_wavelet(x,method='BayesShrink',mode='soft',rescale_sigma=True,channel_axis=-1,convert2ycbcr=True)
    return np.clip(out,0,1).astype(np.float32)

def load_model(path,device):
    # Only load checkpoints produced by this notebook / otherwise trusted.
    state=torch.load(path,map_location='cpu',weights_only=False)
    c=state['config']; model=Denoiser(c['channels'],c['width'],c['blocks'])
    model.load_state_dict(state['model']); return model.to(device).eval()

def ensemble_predict(models,weights,array,device,tile=384,overlap=64,tta=False):
    weights=np.asarray(weights,dtype=float)
    if len(models)!=len(weights) or np.any(weights<0) or weights.sum()<=0:
        raise ValueError('Provide one nonnegative weight per model with positive sum')
    result=np.zeros(array.shape,dtype=np.float32)
    for m,w in zip(models,weights/weights.sum()): result+=float(w)*predict(m,array,device,tile,overlap,tta)
    return result
"
